'use strict';
/* ShiftMemories — vanilla JavaScript, no framework, local-first */
const KEY='shiftmemories:web:data:v1';
const DEFAULT_SETTINGS={name:'',defaultRate:0,defaultPlace:'',notify:true,remindStart:15,remindEnd:10};
const ICONS={
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',
 list:'<path d="M9 6h12M9 12h12M9 18h12"/><path d="M4 6h.01M4 12h.01M4 18h.01" stroke-width="3" stroke-linecap="round"/>',
 upload:'<path d="M12 16V3m0 0L7 8m5-5 5 5M4 16v4a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-4"/>',
 chart:'<path d="M4 20V13m6 7V8m6 12V4m5 16H2"/>',
 settings:'<path d="M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1m0-12.8-2.1 2.1m-8.6 8.6-2.1 2.1"/><circle cx="12" cy="12" r="4"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M4 12H2m20 0h-2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4m0-14.2-1.4 1.4M6.3 17.7l-1.4 1.4"/>',
 euro:'<path d="M18 5.4A8 8 0 1 0 18 18.6M3 10h11M3 14h11"/>',
 check:'<path d="m4 12 5 5L20 6"/>',chevronLeft:'<path d="m15 18-6-6 6-6"/>',chevronRight:'<path d="m9 18 6-6-6-6"/>',
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9zM10 21h4"/>',
 shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="m9 12 2 2 4-4"/>',
 pin:'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0z"/><circle cx="12" cy="10" r="2"/>',
 edit:'<path d="m4 17 13-13 3 3L7 20H4zM14 7l3 3"/>',trash:'<path d="M4 7h16m-14 0 1 14h10l1-14M9 7V4h6v3M10 11v6m4-6v6"/>',
 close:'<path d="M18 6 6 18M6 6l12 12"/>',camera:'<path d="M4 7h4l2-3h4l2 3h4v13H4z"/><circle cx="12" cy="13" r="3"/>',
 file:'<path d="M6 2h8l5 5v15H6zM14 2v5h5M9 13h7M9 17h7"/>',
 download:'<path d="M12 3v13m0 0 5-5m-5 5-5-5M4 18v3h16v-3"/>',
 sparkle:'<path d="m12 2 2.2 7.8L22 12l-7.8 2.2L12 22l-2.2-7.8L2 12l7.8-2.2z"/>',
 play:'<path d="m8 5 12 7-12 7z"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="3"/>',
 refresh:'<path d="M20 6v5h-5M4 18v-5h5"/><path d="M6 9a7 7 0 0 1 12-3l2 5M4 13l2 5a7 7 0 0 0 12-3"/>',
 info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v5m0-9h.01"/>',
 note:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8m-8 4h8m-8 4h5"/>'};
const ico=name=>`<svg aria-hidden="true" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ICONS[name]||ICONS.info}</svg>`;
function hydrateIcons(el=document){el.querySelectorAll('[data-icon]').forEach(node=>{node.innerHTML=ico(node.dataset.icon)})}
function esc(value){return String(value??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function storageRead(){try{const value=JSON.parse(localStorage.getItem(KEY));if(value&&Array.isArray(value.shifts))return {shifts:value.shifts,settings:{...DEFAULT_SETTINGS,...value.settings}}}catch(e){console.warn('Lecture stockage impossible',e)}return {shifts:[],settings:{...DEFAULT_SETTINGS}}}
let state=storageRead();let route='dashboard';let selectedMonth=localDay().slice(0,7);let importCandidates=[];let selectedFile=null;let photoPending=null;let photoRemove=false;let photoUrl=null;let notificationTimer=null;let dbPromise=null;let editingShiftId=null;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){toast('Stockage du navigateur saturé ou interdit. Exportez une sauvegarde.',true);return false}}
function localDay(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function dtDate(day){return new Date(day+'T12:00:00')}
function addDay(day,n){const d=dtDate(day);d.setDate(d.getDate()+n);return localDay(d)}
function niceDate(day,opts={day:'numeric',month:'long',year:'numeric'}){return dtDate(day).toLocaleDateString('fr-FR',opts)}
function dayName(day){return niceDate(day,{weekday:'long'})}
function monthName(month){return dtDate(month+'-01').toLocaleDateString('fr-FR',{month:'long',year:'numeric'}).replace(/^./,x=>x.toUpperCase())}
function money(number){return new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(number)}
function hrs(number){return new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(number)}
function timeFromNow(){return new Date().toTimeString().slice(0,5)}
function isValidDay(day){if(!/^\d{4}-\d{2}-\d{2}$/.test(day))return false;return localDay(dtDate(day))===day}
function shiftMinutes(shift,kind='actual'){const start=kind==='actual'?shift.actualStart:shift.plannedStart;const end=kind==='actual'?shift.actualEnd:shift.plannedEnd;if(!start||!end||!shift.date)return 0;const from=new Date(shift.date+'T'+start+':00');const until=new Date(shift.date+'T'+end+':00');if(until<=from)until.setDate(until.getDate()+1);const minutes=Math.round((until-from)/60000);return Math.max(0,minutes-(Number(shift.breakMinutes)||0))}
function status(shift){return shift.actualStart&&shift.actualEnd?'done':shift.actualStart?'active':'planned'}
function statusTag(shift){const code=status(shift),name=code==='done'?'Terminée':code==='active'?'En cours':'Prévue';return `<span class="badge badge-${code}"><span class="badge-dot"></span>${name}</span>`}
function shiftSorted(values=state.shifts){return [...values].sort((a,b)=>(a.date+a.plannedStart).localeCompare(b.date+b.plannedStart))}
function monthShifts(month=selectedMonth){return state.shifts.filter(s=>s.date.startsWith(month))}
function totals(month=selectedMonth){const shifts=monthShifts(month);const done=shifts.filter(s=>status(s)==='done');return {planned:shifts.reduce((v,s)=>v+shiftMinutes(s,'planned'),0),actual:done.reduce((v,s)=>v+shiftMinutes(s,'actual'),0),amount:done.reduce((v,s)=>v+(shiftMinutes(s,'actual')/60)*(Number(s.rate)||0),0),priced:done.filter(s=>Number(s.rate)>0).length,done:done.length,plannedDays:shifts.length,workingDays:new Set(done.map(s=>s.date)).size}}
function shiftDateTime(s,type){const source=type==='end'?s.plannedEnd:s.plannedStart;if(!source||!s.date)return null;const d=new Date(s.date+'T'+source+':00');if(type==='end'&&s.plannedStart&&s.plannedEnd<=s.plannedStart)d.setDate(d.getDate()+1);return d}
function toast(message,error=false){const root=document.getElementById('toast-root');const div=document.createElement('div');div.className='toast'+(error?' error':'');div.textContent=message;root.appendChild(div);setTimeout(()=>div.remove(),4400)}
function render(){const names={dashboard:'Vue d’ensemble',calendar:'Calendrier',days:'Mes journées',import:'Importer un planning',reports:'Bilans & exports',settings:'Paramètres'};document.getElementById('route-name').textContent=names[route]||names.dashboard;document.getElementById('today-chip').textContent=niceDate(localDay(),{weekday:'long',day:'numeric',month:'long'});document.querySelectorAll('[data-route]').forEach(btn=>{btn.classList.toggle('active',btn.dataset.route===route);if(btn.classList.contains('nav-item'))btn.setAttribute('aria-current',btn.dataset.route===route?'page':'false')});const view=document.getElementById('view');const html={dashboard:dashboardHtml,calendar:calendarHtml,days:daysHtml,import:importHtml,reports:reportsHtml,settings:settingsHtml}[route]();view.innerHTML=html;hydrateIcons(view);document.title=`${names[route]} · ShiftMemories`;}
function navigate(value){route=value;document.getElementById('sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'})}
function statCard(label,value,unit,detail,icon,variation){return `<div class="stat card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ${variation||''}">${ico(icon)}</span></div><div class="stat-value">${value} <small>${unit}</small></div><div class="stat-desc">${detail}</div></div>`}
function emptyHtml(icon,title,body,action='',label=''){return `<div class="empty"><div class="empty-icon">${ico(icon)}</div><h3>${title}</h3><p>${body}</p>${action?`<button class="btn btn-secondary" data-action="${action}">${ico('plus')}${label}</button>`:''}</div>`}
function rowHtml(s){return `<div class="shift-row"><div class="date-tile"><strong>${Number(s.date.slice(-2))}</strong><small>${niceDate(s.date,{month:'short'})}</small></div><div class="shift-main"><strong>${esc(s.establishment||'Service infirmier')}</strong><p>${esc(dayName(s.date))} · ${s.plannedStart} – ${s.plannedEnd}</p></div><div class="shift-time">${statusTag(s)}</div><button data-action="edit-shift" data-id="${esc(s.id)}" class="icon-button" aria-label="Modifier la journée">${ico('chevronRight')}</button></div>`}
function dashboardHtml(){const today=localDay();const t=totals(today.slice(0,7));const name=state.settings.name.trim()?` ${esc(state.settings.name.trim())}`:'';const hour=new Date().getHours();const greeting=hour<18?'Bonjour':'Bonsoir';const todays=shiftSorted().filter(s=>s.date===today);const active=shiftSorted().find(s=>status(s)==='active'&&s.date>=addDay(today,-2));const featured=active||todays.find(s=>status(s)==='planned')||shiftSorted().find(s=>s.date>=today&&status(s)==='planned');const upcoming=shiftSorted().filter(s=>(s.date>=today||status(s)==='active')&&status(s)!=='done').slice(0,5);const firstDay=todays.find(s=>status(s)==='planned');const quick=active?`<button class="btn btn-light" data-action="end-shift" data-id="${esc(active.id)}">${ico('stop')} Terminer mon service</button>`:firstDay?`<button class="btn btn-light" data-action="start-shift" data-id="${esc(firstDay.id)}">${ico('play')} Démarrer mon service</button>`:`<button class="btn btn-light" data-action="new-shift">${ico('plus')} Ajouter un service</button>`;return `<div class="hero"><div class="hero-left"><div class="hero-kicker">VOTRE ESPACE DE TRAVAIL</div><h1>${greeting}${name} <span>✳</span><br><em>Un jour à la fois.</em></h1><div class="hero-copy">Vos gardes, vos heures, vos notes et votre équilibre. Tout est là, simplement.</div><div class="hero-actions">${quick}<button class="btn btn-ghost" style="color:#c0ebd7" data-route="calendar">Mon planning ${ico('arrow')}</button></div></div><div class="hero-right">${featured?`<div class="shift-feature"><div class="feature-top"><span>${status(featured)==='active'?'✦ SERVICE EN COURS':featured.date===today?'✦ AUJOURD’HUI':'✦ PROCHAIN SERVICE'}</span><span class="mini-status ${status(featured)==='planned'?'pending':''}">${status(featured)==='active'?'En cours':status(featured)==='done'?'Terminé':'À venir'}</span></div><div class="feature-date">${esc(niceDate(featured.date,{weekday:'long',day:'numeric',month:'long'}))}</div><div class="feature-place">${ico('pin')} ${esc(featured.establishment||'Lieu non renseigné')}</div><div class="feature-hours"><span>${esc(featured.plannedStart)}</span>${ico('arrow')}<span>${esc(featured.plannedEnd)}</span></div><div class="feature-foot"><span>${hrs(shiftMinutes(featured,'planned')/60)} h prévues</span><span>${featured.breakMinutes?`${Number(featured.breakMinutes)} min de pause`:'Sans pause déduite'}</span></div></div>`:`<div class="shift-feature"><div class="feature-top">✦ PROCHAINE GARDE</div><p class="hero-empty" style="margin:20px 0 11px">Votre planning est prêt à accueillir sa première journée.</p><button class="btn btn-light" data-route="import">${ico('upload')} Importer mon planning</button></div>`}</div></div>
 <div class="stat-grid">${statCard('HEURES EFFECTUÉES',hrs(t.actual/60),'h','Ce mois-ci', 'clock')}${statCard('HEURES PRÉVUES',hrs(t.planned/60),'h','Sur le planning', 'sun','sun')}${statCard('JOURS TRAVAILLÉS',String(t.workingDays),t.workingDays===1?'jour':'jours',`${t.done} service${t.done===1?'':'s'} terminé${t.done===1?'':'s'}`,'calendar','purple')}${statCard('MONTANT ESTIMÉ',t.priced?hrs(t.amount):'—',t.priced?'€':'',t.priced?'Selon vos tarifs saisis':'Renseignez vos tarifs','euro','blue')}</div>
 <div class="dash-main"><div><div class="section-heading"><div><h2>Mes prochains services</h2><p>Tout ce qui arrive, au même endroit</p></div><button class="text-btn" data-route="calendar">Voir le calendrier ${ico('arrow')}</button></div><div class="card list-card">${upcoming.length?upcoming.map(rowHtml).join(''):emptyHtml('calendar','Votre planning est vide','Ajoutez une journée ou importez vos horaires.','new-shift','Ajouter une journée')}</div></div><div><div class="section-heading"><div><h2>Votre mois en bref</h2><p>${esc(monthName(today.slice(0,7)))}</p></div></div><div class="card today-info"><h3>Vous avancez à votre rythme</h3><p>Proportion des heures prévues déjà effectuées.</p><div class="today-circle">${t.planned?Math.round(t.actual/t.planned*100)+'%':'0%'}</div><div style="text-align:center;font-size:11px;color:#839a8b">${hrs(t.actual/60)} h sur ${hrs(t.planned/60)} h prévues</div><div class="side-note">${ico('sparkle')} Petit rappel : pensez à noter votre heure de fin pour obtenir un bilan précis.</div><div class="quick-actions"><button class="btn btn-secondary" data-route="days">${ico('note')} Mes notes</button><button class="btn btn-secondary" data-route="reports">${ico('chart')} Mon bilan</button></div></div></div></div>`}
function calendarHtml(){const [year,month]=selectedMonth.split('-').map(Number);const first=new Date(year,month-1,1);const offset=(first.getDay()+6)%7;const count=new Date(year,month,0).getDate();const days=Math.ceil((offset+count)/7)*7;let cells='';for(let i=0;i<days;i++){const n=i-offset+1;if(n<1||n>count){cells+='<div class="day-cell off" aria-hidden="true"></div>';continue}const d=`${year}-${String(month).padStart(2,'0')}-${String(n).padStart(2,'0')}`;const entries=shiftSorted().filter(s=>s.date===d);cells+=`<button class="day-cell ${d===localDay()?'today':''}" data-action="view-day" data-date="${d}" aria-label="${esc(niceDate(d))}, ${entries.length} services"><span class="day-head">${d===localDay()?`<span>${n}</span>`:n}</span>${entries.slice(0,2).map(s=>`<span class="day-shift ${status(s)}">${esc(s.plannedStart)}–${esc(s.plannedEnd)}</span>`).join('')}${entries.length>2?`<span style="font-size:9px;color:#8ea99d">+${entries.length-2} autre(s)</span>`:''}</button>`}return `<div class="heading-row"><div><div class="eyebrow">MON ORGANISATION</div><h1>Mon calendrier<span style="color:#8bc9a9">.</span></h1><p>Votre planning du mois, toujours sous les yeux.</p></div><button class="btn btn-primary" data-action="new-shift">${ico('plus')} Ajouter un service</button></div><div class="toolbar"><div class="month-switch"><button data-action="prev-month" aria-label="Mois précédent">${ico('chevronLeft')}</button><strong>${esc(monthName(selectedMonth))}</strong><button data-action="next-month" aria-label="Mois suivant">${ico('chevronRight')}</button></div><button class="btn btn-outline" data-action="today-month">Aujourd’hui</button></div><div class="calendar card"><div class="calendar-days">${['LUN','MAR','MER','JEU','VEN','SAM','DIM'].map(s=>`<div class="weekday">${s}</div>`).join('')}${cells}</div><div class="calendar-legend"><span><b class="legend-dot"></b> Service prévu</span><span><b class="legend-dot active"></b> En cours</span><span><b class="legend-dot done"></b> Service terminé</span><span style="margin-left:auto">${monthShifts().length} service(s) ce mois</span></div></div>`}
function daysHtml(){const entries=shiftSorted(monthShifts()).reverse();return `<div class="heading-row"><div><div class="eyebrow">MON JOURNAL DE BORD</div><h1>Mes journées<span style="color:#8bc9a9">.</span></h1><p>Chaque service, chaque détail, au même endroit.</p></div><button class="btn btn-primary" data-action="new-shift">${ico('plus')} Nouvelle journée</button></div><div class="toolbar"><div class="month-switch"><button data-action="prev-month">${ico('chevronLeft')}</button><strong>${esc(monthName(selectedMonth))}</strong><button data-action="next-month">${ico('chevronRight')}</button></div><span class="pill">${entries.length} service(s)</span></div><div class="day-list">${entries.length?entries.map(s=>`<article class="day-detail card"><div class="detail-date"><div class="week">${esc(dayName(s.date))}</div><div class="big">${Number(s.date.slice(-2))}</div><div class="week">${esc(niceDate(s.date,{month:'short'}))}</div></div><div class="detail-body"><strong>${esc(s.establishment||'Service infirmier')}</strong><div class="sub">Prévu : ${esc(s.plannedStart)} – ${esc(s.plannedEnd)}${s.actualStart&&s.actualEnd?` · Réalisé : ${esc(s.actualStart)} – ${esc(s.actualEnd)}`:''}</div><div class="detail-tags">${statusTag(s)}${s.note?`<span class="tag">${ico('note')} Note</span>`:''}${s.hasPhoto?`<span class="tag">${ico('camera')} Photo</span>`:''}</div></div><div class="detail-side"><strong>${status(s)==='done'?hrs(shiftMinutes(s,'actual')/60):hrs(shiftMinutes(s,'planned')/60)} h</strong><small>${status(s)==='done'?'effectuées':'prévues'}</small></div><div class="day-controls"><button class="icon-button" data-action="edit-shift" data-id="${esc(s.id)}" aria-label="Modifier">${ico('edit')}</button><button class="icon-button" data-action="delete-shift" data-id="${esc(s.id)}" aria-label="Supprimer">${ico('trash')}</button></div></article>`).join(''):emptyHtml('list','Aucune journée pour ce mois','Votre journal commencera dès la première journée enregistrée.','new-shift','Ajouter une journée')}</div>`}
function reportChart(month){const shifts=monthShifts(month);const groups=[];for(let i=0;i<5;i++){const start=i*7+1,end=Math.min((i+1)*7,31);groups.push(shifts.filter(s=>Number(s.date.slice(-2))>=start&&Number(s.date.slice(-2))<=end&&status(s)==='done').reduce((v,s)=>v+shiftMinutes(s,'actual')/60,0))}const max=Math.max(...groups,1);return `<div class="bars">${groups.map((h,i)=>`<div class="bar-col"><div class="bar" style="height:${h?Math.max(3,h/max*140):0}px" title="${hrs(h)} h"></div><small>S${i+1}</small></div>`).join('')}</div>`}
function reportsHtml(){const t=totals();const entries=shiftSorted(monthShifts());return `<div class="print-only"><h1>ShiftMemories — bilan mensuel</h1><p>${esc(monthName(selectedMonth))} · Généré le ${esc(niceDate(localDay()))}</p></div><div class="heading-row no-print"><div><div class="eyebrow">MON TEMPS, MES CHIFFRES</div><h1>Bilans & exports<span style="color:#8bc9a9">.</span></h1><p>Vos heures et votre activité en toute clarté.</p></div><button class="btn btn-primary" data-action="print-report">${ico('download')} Exporter en PDF</button></div><div class="toolbar no-print"><div class="month-switch"><button data-action="prev-month">${ico('chevronLeft')}</button><strong>${esc(monthName(selectedMonth))}</strong><button data-action="next-month">${ico('chevronRight')}</button></div><span class="pill">Bilan mensuel</span></div><div class="stat-grid" style="margin:0 0 18px">${statCard('HEURES EFFECTUÉES',hrs(t.actual/60),'h','Heures confirmées','clock')}${statCard('HEURES PRÉVUES',hrs(t.planned/60),'h','Selon les plannings','calendar','sun')}${statCard('JOURS TRAVAILLÉS',t.workingDays,t.workingDays===1?'jour':'jours',`${t.done} service${t.done===1?'':'s'} terminé${t.done===1?'':'s'}`,'check','purple')}${statCard('MONTANT ESTIMÉ',t.priced?hrs(t.amount):'—',t.priced?'€':'','Hors charges et cotisations','euro','blue')}</div><div class="report-overview"><div class="report-chart card"><h3>Activité sur le mois</h3><p class="text-sm muted">Heures réellement effectuées, semaine par semaine</p>${reportChart(selectedMonth)}<div class="chart-caption">* Services terminés uniquement.</div></div><div class="report-side card"><h3>Résumé du mois</h3><p>Les chiffres essentiels, en un coup d’œil.</p><div class="big-total">${hrs(t.actual/60)}<span style="font-size:17px;color:#88a798"> h</span></div><div class="muted text-sm" style="margin-bottom:18px">travaillées</div><div class="line-stats"><span>Heures planifiées</span><strong>${hrs(t.planned/60)} h</strong></div><div class="line-stats"><span>Services terminés</span><strong>${t.done}</strong></div><div class="line-stats"><span>Rémunération estimée</span><strong>${t.priced?money(t.amount):'Non renseignée'}</strong></div></div></div><div class="section-heading exports no-print"><div><h2>Exporter mes données</h2><p>Sauvegardes, calendrier et feuilles d’heures.</p></div></div><div class="export-grid no-print"><div class="export-card card"><div class="export-icon">${ico('file')}</div><strong>Feuille d’heures CSV</strong><p>Pour Excel, Numbers et la comptabilité.</p><button class="text-btn" data-action="export-csv">Télécharger ${ico('arrow')}</button></div><div class="export-card card"><div class="export-icon">${ico('calendar')}</div><strong>Calendrier avec rappels</strong><p>Fichier .ics à importer dans le calendrier du téléphone.</p><button class="text-btn" data-action="export-ics">Télécharger ${ico('arrow')}</button></div><div class="export-card card"><div class="export-icon">${ico('shield')}</div><strong>Sauvegarde complète</strong><p>Gardes, notes, paramètres et photos en JSON.</p><button class="text-btn" data-action="export-backup">Sauvegarder ${ico('arrow')}</button></div></div><div class="section-heading"><div><h2>Détail des services</h2><p>Heures par journée enregistrée.</p></div></div><div class="card list-card">${entries.length?entries.map(s=>`<div class="shift-row"><div class="date-tile"><strong>${Number(s.date.slice(-2))}</strong><small>${esc(niceDate(s.date,{month:'short'}))}</small></div><div class="shift-main"><strong>${esc(s.establishment||'Service infirmier')}</strong><p>${esc(s.plannedStart)}–${esc(s.plannedEnd)}${status(s)==='done'?` · Fait : ${esc(s.actualStart)}–${esc(s.actualEnd)}`:''}</p></div><div style="text-align:right"><strong style="font-size:12px">${hrs(shiftMinutes(s,status(s)==='done'?'actual':'planned')/60)} h</strong><div style="margin-top:4px">${statusTag(s)}</div></div></div>`).join(''):emptyHtml('chart','Pas encore de données','Vos services renseignés apparaîtront ici.')}</div><div class="setting-note" style="margin-top:17px">Montants indicatifs calculés à partir des heures saisies et des tarifs renseignés. Ils ne tiennent pas compte des charges, cotisations ou règles contractuelles.</div>`}
function importHtml(){return `<div class="heading-row"><div><div class="eyebrow">IMPORT INTELLIGENT</div><h1>Importer mon planning<span style="color:#8bc9a9">.</span></h1><p>Une photo ou un PDF, et vos horaires prennent forme.</p></div></div><div class="import-drop" id="drop-zone"><div class="empty-icon">${ico('upload')}</div><h3>Glissez votre planning ici</h3><p>PDF, JPG, PNG ou WEBP · à vérifier avant enregistrement</p><button class="btn btn-primary" data-action="choose-import">${ico('plus')} Choisir un fichier</button><input type="file" id="import-file" accept="application/pdf,.pdf,image/png,image/jpeg,image/webp" hidden /></div><div id="import-progress"></div><div class="section-heading"><div><h2>Ou coller les horaires</h2><p>Exemple : 02/11/2026 07:00 - 14:00</p></div></div><div class="card" style="padding:22px"><div class="form-grid"><div class="field"><label for="import-month">Mois du planning</label><input type="month" id="import-month" value="${esc(selectedMonth)}"></div><div class="field"><label for="import-place">Établissement (facultatif)</label><input id="import-place" type="text" placeholder="Hôpital, cabinet, structure..." value="${esc(state.settings.defaultPlace)}"></div></div><div class="field" style="margin-top:15px"><label for="import-text">Texte reconnu / saisi manuellement</label><textarea id="import-text" style="min-height:110px" placeholder="Lundi 02/11/2026 07h00 - 14h15&#10;Mardi 03/11/2026 19h00 - 07h00"></textarea><small>La lecture automatique doit être vérifiée : les codes de service sans heures ne peuvent pas être interprétés avec certitude.</small></div><div style="margin-top:15px"><button class="btn btn-secondary" data-action="parse-import">${ico('sparkle')} Reconnaître les horaires</button></div></div><div id="import-preview"></div><div class="setting-note" style="margin-top:20px">${ico('shield')} La saisie, les notes et les photos de journées restent sur votre appareil. La reconnaissance d’image ou de PDF nécessite une connexion pour charger les bibliothèques techniques. Ne mettez aucune donnée personnelle de patient dans les fichiers ou notes.</div>`}
function settingsHtml(){const s=state.settings;return `<div class="heading-row"><div><div class="eyebrow">MON ESPACE</div><h1>Paramètres<span style="color:#8bc9a9">.</span></h1><p>Un espace personnalisé, pensé pour vous.</p></div></div><div class="settings-layout"><div><form id="settings-form" class="card settings-card"><h3>Mes préférences</h3><p>Raccourcis pour saisir vos journées plus vite.</p><div class="field"><label for="set-name">Prénom (facultatif)</label><input id="set-name" name="name" value="${esc(s.name)}" placeholder="Comment vous appeler ?"></div><div class="field" style="margin-top:15px"><label for="set-place">Établissement habituel</label><input id="set-place" name="defaultPlace" value="${esc(s.defaultPlace)}" placeholder="Ex. : Cabinet infirmier"></div><div class="field" style="margin-top:15px"><label for="set-rate">Tarif horaire par défaut (€)</label><input id="set-rate" name="defaultRate" type="number" min="0" step="0.01" value="${Number(s.defaultRate)||0}"><small>Facultatif ; utilisé uniquement pour estimer le revenu.</small></div><button type="submit" class="btn btn-primary" style="margin-top:18px">${ico('check')} Enregistrer</button></form><div class="card settings-card"><h3>Sauvegarder ou restaurer</h3><p>Conservez une copie de vos données, notamment avant de changer de téléphone.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-secondary" data-action="export-backup">${ico('download')} Sauvegarder</button><button class="btn btn-outline" data-action="restore-backup">${ico('refresh')} Restaurer</button></div></div></div><div><form id="reminders-form" class="card settings-card"><h3>Rappels de service</h3><p>Un petit coup de pouce avant le début et la fin de vos gardes.</p><label class="toggle"><input name="notify" type="checkbox" ${s.notify?'checked':''} /><span>Activer les rappels pendant l’ouverture de l’application</span></label><div class="form-grid" style="margin-top:19px"><div class="field"><label for="rem-start">Avant le début (min)</label><input id="rem-start" type="number" min="0" max="180" name="remindStart" value="${Number(s.remindStart)}"></div><div class="field"><label for="rem-end">Avant la fin (min)</label><input id="rem-end" type="number" min="0" max="180" name="remindEnd" value="${Number(s.remindEnd)}"></div></div><div style="margin-top:17px;display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-primary" type="submit">${ico('check')} Enregistrer</button><button class="btn btn-outline" type="button" data-action="permission">${ico('bell')} Autoriser les notifications</button></div><p class="helper" style="margin-top:14px">Pour être alerté même lorsque l’application est fermée, exportez vos gardes au format .ics et importez-les dans votre calendrier avec les notifications activées.</p></form><div class="setting-note warn-note">${ico('info')} <strong>Confidentialité.</strong> Vos données sont stockées dans le navigateur de cet appareil. Elles peuvent disparaître si ses données sont effacées. Évitez toute information permettant d’identifier un patient.</div><div class="setting-note" style="margin-top:14px">${ico('shield')} Application installable en mode PWA sur un site HTTPS. Pas de compte ni d’envoi automatique vers un serveur.</div></div></div>`}
function shiftForm(s){const date=s?.date||localDay();const plannedStart=s?.plannedStart||'07:00';const plannedEnd=s?.plannedEnd||'14:00';const hasPhoto=!!s?.hasPhoto;return `<div class="modal-backdrop" id="shift-backdrop"><section class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="shift-modal-title"><div class="modal-head"><div><div class="eyebrow">JOURNAL DE SERVICE</div><h2 id="shift-modal-title">${s?.id?'Modifier ma journée':'Nouvelle journée'}</h2></div><button class="icon-button" data-action="close-modal" aria-label="Fermer">${ico('close')}</button></div><form id="shift-form"><input type="hidden" name="shiftId" value="${esc(s?.id||'')}"><div class="form-grid"><div class="field"><label for="shift-date">Date de la journée *</label><input required id="shift-date" name="date" type="date" value="${esc(date)}"></div><div class="field"><label for="shift-place">Établissement</label><input id="shift-place" name="establishment" placeholder="Cabinet, service..." value="${esc(s?.establishment??state.settings.defaultPlace)}"></div></div><div class="form-section"><div class="form-section-heading">${ico('calendar')} Horaires prévus</div><div class="form-grid"><div class="field"><label for="planned-start">Début prévu *</label><input required id="planned-start" name="plannedStart" type="time" value="${esc(plannedStart)}"></div><div class="field"><label for="planned-end">Fin prévue *</label><input required id="planned-end" name="plannedEnd" type="time" value="${esc(plannedEnd)}"></div></div></div><div class="form-section"><div class="form-section-heading">${ico('clock')} Heures réellement travaillées</div><div class="form-grid"><div class="field"><label for="actual-start">Heure d’arrivée</label><input id="actual-start" name="actualStart" type="time" value="${esc(s?.actualStart||'')}"></div><div class="field"><label for="actual-end">Heure de départ</label><input id="actual-end" name="actualEnd" type="time" value="${esc(s?.actualEnd||'')}"></div></div><p class="helper" style="margin-top:8px">Laissez vide si la garde n’a pas encore commencé. Les gardes de nuit sont calculées automatiquement.</p></div><div class="form-section"><div class="form-section-heading">${ico('euro')} Pauses & rémunération</div><div class="form-grid"><div class="field"><label for="shift-break">Pause non payée (minutes)</label><input id="shift-break" type="number" name="breakMinutes" min="0" max="1440" step="1" value="${Number(s?.breakMinutes)||0}"></div><div class="field"><label for="shift-rate">Tarif horaire (€)</label><input id="shift-rate" type="number" name="rate" min="0" max="99999" step="0.01" value="${Number(s?.rate??state.settings.defaultRate)||0}"></div></div></div><div class="form-section"><div class="form-section-heading">${ico('note')} Notes de la journée</div><div class="field"><label for="shift-note">Mémo personnel (facultatif)</label><textarea id="shift-note" name="note" placeholder="Éléments d’organisation, ressentis, tâches à ne pas oublier... Pas de données patient.">${esc(s?.note||'')}</textarea></div><div class="field" style="margin-top:16px"><label>Photo de la journée (facultative)</label><div class="photo-input"><label class="btn btn-secondary" for="shift-photo">${ico('camera')} ${hasPhoto?'Changer la photo':'Ajouter une photo'}</label><input id="shift-photo" type="file" accept="image/*" hidden></div><div id="photo-preview-container">${hasPhoto?'<p class="helper">Chargement de la photo...</p>':''}</div><button id="remove-photo" class="text-btn photo-clear" type="button" data-action="remove-photo" ${hasPhoto?'':'hidden'}>Supprimer la photo</button></div></div><div class="modal-actions"><button type="button" class="btn btn-outline" data-action="close-modal">Annuler</button><button type="submit" class="btn btn-primary">${ico('check')} Enregistrer</button></div></form></section></div>`}
function openShiftModal(id=null,date=null){editingShiftId=id;photoPending=null;photoRemove=false;const existing=id?state.shifts.find(s=>s.id===id):null;const model=existing||{date:date||localDay()};document.getElementById('modal-root').innerHTML=shiftForm(existing||model);hydrateIcons(document.getElementById('modal-root'));document.body.style.overflow='hidden';if(existing?.hasPhoto)loadPhotoPreview(existing.id)}
function closeModal(){document.getElementById('modal-root').innerHTML='';document.body.style.overflow='';photoPending=null;photoRemove=false;editingShiftId=null;if(photoUrl){URL.revokeObjectURL(photoUrl);photoUrl=null}}
function viewDay(day){const entries=shiftSorted().filter(s=>s.date===day);if(entries.length===0){openShiftModal(null,day);return}document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal-panel" role="dialog" aria-modal="true"><div class="modal-head"><div><div class="eyebrow">JOURNÉE DU</div><h2>${esc(niceDate(day))}</h2></div><button class="icon-button" data-action="close-modal">${ico('close')}</button></div><div class="card list-card">${entries.map(rowHtml).join('')}</div><button class="btn btn-primary" style="margin-top:23px" data-action="new-shift" data-date="${day}">${ico('plus')} Ajouter un autre service</button></section></div>`;hydrateIcons(document.getElementById('modal-root'));document.body.style.overflow='hidden'}
function uniqueId(){return crypto.randomUUID?crypto.randomUUID():'shift-'+Date.now()+'-'+Math.random().toString(16).slice(2)}
async function saveShift(form){const f=new FormData(form);const date=String(f.get('date')||'');if(!isValidDay(date)){toast('Date invalide.',true);return}const plannedStart=f.get('plannedStart'),plannedEnd=f.get('plannedEnd'),actualStart=f.get('actualStart')||'',actualEnd=f.get('actualEnd')||'';if(!plannedStart||!plannedEnd){toast('Indiquez les horaires prévus.',true);return}if(actualEnd&&!actualStart){toast('Ajoutez une heure d’arrivée avant une heure de départ.',true);return}const existing=state.shifts.find(s=>s.id===f.get('shiftId'));const id=existing?.id||uniqueId();const data={id,date,establishment:String(f.get('establishment')||'').trim().slice(0,160),plannedStart,plannedEnd,actualStart,actualEnd,breakMinutes:Math.max(0,Number(f.get('breakMinutes'))||0),rate:Math.max(0,Number(f.get('rate'))||0),note:String(f.get('note')||'').slice(0,5000),hasPhoto:photoPending?true:photoRemove?false:!!existing?.hasPhoto,updatedAt:new Date().toISOString()};if(shiftMinutes(data,'planned')<=0&&data.breakMinutes>0){toast('La pause ne peut pas dépasser la durée du service.',true);return}if(data.actualEnd&&shiftMinutes(data,'actual')<=0&&data.breakMinutes>0){toast('La pause dépasse la durée réellement travaillée.',true);return}const previous=existing?{...existing}:null;if(existing)Object.assign(existing,data);else state.shifts.push(data);if(!persist()){if(existing)Object.assign(existing,previous);else state.shifts=state.shifts.filter(s=>s.id!==id);return}try{if(photoPending)await idbPutPhoto(id,photoPending);else if(photoRemove)await idbDeletePhoto(id)}catch(err){data.hasPhoto=false;persist();toast('Photo non enregistrée (stockage navigateur indisponible).',true)}closeModal();render();toast('Journée enregistrée avec succès.');checkReminders()}
async function deleteShift(id){const s=state.shifts.find(v=>v.id===id);if(!s)return;if(!confirm(`Supprimer le service du ${niceDate(s.date)} ?`))return;state.shifts=state.shifts.filter(v=>v.id!==id);persist();try{await idbDeletePhoto(id)}catch(_e){}render();toast('Service supprimé.')}
function markStart(id){const s=state.shifts.find(x=>x.id===id);if(!s)return;if(s.actualStart&&!confirm('Remplacer l’heure de début déjà enregistrée ?'))return;s.actualStart=timeFromNow();s.actualEnd='';s.updatedAt=new Date().toISOString();persist();render();toast('Début de service enregistré à '+s.actualStart)}
function markEnd(id){const s=state.shifts.find(x=>x.id===id);if(!s)return;if(!s.actualStart){toast('Enregistrez d’abord le début du service.',true);return}s.actualEnd=timeFromNow();s.updatedAt=new Date().toISOString();persist();render();toast('Fin de service enregistrée à '+s.actualEnd)}
function db(){if(!('indexedDB' in window))return Promise.reject(Error('IndexedDB indisponible'));if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('shiftmemories-web-photos',1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains('photos'))req.result.createObjectStore('photos')};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return dbPromise}
async function idbPutPhoto(id,file){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('photos','readwrite');tx.objectStore('photos').put(file,id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
async function idbGetPhoto(id){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('photos','readonly');const request=tx.objectStore('photos').get(id);request.onsuccess=()=>resolve(request.result||null);request.onerror=()=>reject(request.error)})}
async function idbClearPhotos(){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('photos','readwrite');tx.objectStore('photos').clear();tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
async function idbDeletePhoto(id){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('photos','readwrite');tx.objectStore('photos').delete(id);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
function blobDataURL(blob){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(blob)})}
function dataURLBlob(data){const [head,b64]=data.split(',');const content=atob(b64);const arr=new Uint8Array(content.length);for(let i=0;i<content.length;i++)arr[i]=content.charCodeAt(i);return new Blob([arr],{type:head.match(/data:([^;]+)/)?.[1]||'image/jpeg'})}
async function compressPhoto(file){return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file);const img=new Image();img.onload=()=>{const scale=Math.min(1,1400/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{URL.revokeObjectURL(url);if(blob)resolve(blob);else reject(Error('Impossible de préparer cette photo'))},'image/jpeg',.78)};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Photo non lisible'))};img.src=url})}
async function loadPhotoPreview(id){try{const blob=await idbGetPhoto(id);if(blob&&editingShiftId===id){photoUrl=URL.createObjectURL(blob);const target=document.getElementById('photo-preview-container');if(target)target.innerHTML=`<img class="photo-preview" src="${photoUrl}" alt="Photo de cette journée">`}}catch(e){const target=document.getElementById('photo-preview-container');if(target)target.innerHTML='<p class="helper">Photo indisponible.</p>'}}
async function onPhotoChange(file){if(!file)return;try{const blob=await compressPhoto(file);photoPending=blob;photoRemove=false;if(photoUrl){URL.revokeObjectURL(photoUrl);photoUrl=null}photoUrl=URL.createObjectURL(blob);const target=document.getElementById('photo-preview-container');if(target)target.innerHTML=`<img class="photo-preview" src="${photoUrl}" alt="Aperçu de la photo">`;const remove=document.getElementById('remove-photo');if(remove)remove.hidden=false;toast('Photo prête à être enregistrée.')}catch(e){toast(e.message,true)}}
function saveFile(name,data,type){const blob=new Blob([data],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function csvCell(value){return '"'+String(value??'').replaceAll('"','""')+'"'}
function exportCsv(){const rows=[['Date','Établissement','Début prévu','Fin prévue','Début réel','Fin réelle','Pause (min)','Heures prévues','Heures effectuées','Tarif (EUR/h)','Montant estimé (EUR)','Statut','Notes']];shiftSorted(monthShifts()).forEach(s=>rows.push([s.date,s.establishment,s.plannedStart,s.plannedEnd,s.actualStart,s.actualEnd,s.breakMinutes,(shiftMinutes(s,'planned')/60).toFixed(2).replace('.',','),status(s)==='done'?(shiftMinutes(s,'actual')/60).toFixed(2).replace('.',','):'',s.rate||'',status(s)==='done'?((shiftMinutes(s,'actual')/60)*(s.rate||0)).toFixed(2).replace('.',','):'',status(s),s.note]));saveFile('ShiftMemories-heures-'+selectedMonth+'.csv','\ufeff'+rows.map(row=>row.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');toast('Feuille d’heures CSV exportée.')}
function icsDate(date){return date.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z')}
function icsEscape(value){return String(value).replaceAll('\\','\\\\').replaceAll(';','\\;').replaceAll(',','\\,').replaceAll('\n','\\n')}
function exportICS(){let events=[];const now=icsDate(new Date());for(const s of shiftSorted(monthShifts())){const begin=shiftDateTime(s,'start'),end=shiftDateTime(s,'end');if(!begin||!end)continue;for(const type of ['start','end']){const eventStart=type==='start'?begin:end;const eventEnd=new Date(eventStart.getTime()+(type==='start'?Math.max(5,(end-begin)/60000):5)*60000);const offset=type==='start'?state.settings.remindStart:state.settings.remindEnd;events.push(['BEGIN:VEVENT',`UID:${s.id}-${type}@shiftmemories.local`,`DTSTAMP:${now}`,`DTSTART:${icsDate(eventStart)}`,`DTEND:${icsDate(eventEnd)}`,`SUMMARY:${icsEscape(type==='start'?'Début de garde — '+(s.establishment||'ShiftMemories'):'Fin de garde — '+(s.establishment||'ShiftMemories'))}`,`DESCRIPTION:${icsEscape('Service prévu : '+s.plannedStart+' à '+s.plannedEnd)}`,'BEGIN:VALARM',`TRIGGER:-PT${Math.max(0,Math.floor(Number(offset)||0))}M`,'ACTION:DISPLAY',`DESCRIPTION:${icsEscape(type==='start'?'Début de garde bientôt':'Fin de garde bientôt')}`,'END:VALARM','END:VEVENT'].join('\r\n'))}}const content=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//ShiftMemories//Planning infirmier//FR','CALSCALE:GREGORIAN','METHOD:PUBLISH',...events,'END:VCALENDAR'].join('\r\n');saveFile(`ShiftMemories-calendrier-${selectedMonth}.ics`,content,'text/calendar;charset=utf-8');toast(events.length?`Calendrier exporté (${events.length/2} services).`:'Calendrier vide exporté.')}
async function exportBackup(){const photos={};for(const s of state.shifts.filter(x=>x.hasPhoto)){try{const blob=await idbGetPhoto(s.id);if(blob)photos[s.id]=await blobDataURL(blob)}catch(e){console.warn('Sauvegarde photo indisponible',e)}}const pack={app:'ShiftMemories',version:1,savedAt:new Date().toISOString(),settings:state.settings,shifts:state.shifts,photos};saveFile('ShiftMemories-sauvegarde-'+localDay()+'.json',JSON.stringify(pack,null,2),'application/json');toast('Sauvegarde complète créée.')}
async function restoreBackup(file){try{const json=JSON.parse(await file.text());if(json.app!=='ShiftMemories'||!Array.isArray(json.shifts)||json.shifts.some(x=>!isValidDay(x.date)||typeof x.id!=='string'))throw Error('Fichier non reconnu ou incomplet.');if(!confirm(`Remplacer les données actuelles par ${json.shifts.length} journées de cette sauvegarde ?`))return;state={shifts:json.shifts,settings:{...DEFAULT_SETTINGS,...json.settings}};if(!persist())return;try{await idbClearPhotos()}catch(e){console.warn('Nettoyage photos indisponible',e)}if(json.photos&&typeof json.photos==='object'){for(const [id,val] of Object.entries(json.photos)){try{await idbPutPhoto(id,dataURLBlob(val))}catch(e){console.warn(e)}}}route='dashboard';selectedMonth=localDay().slice(0,7);render();toast('Sauvegarde restaurée.')}catch(e){toast('Restauration impossible : '+e.message,true)}}
async function permission(){if(!('Notification' in window)){toast('Notifications non prises en charge ici.',true);return}if(!window.isSecureContext){toast('Notifications nécessitent HTTPS ou localhost.',true);return}try{const result=await Notification.requestPermission();toast(result==='granted'?'Notifications autorisées.':'Permission de notifications non accordée.')}catch(e){toast('Impossible d’autoriser les notifications.',true)}}
async function displayNotification(title,body){if(!('Notification' in window)||Notification.permission!=='granted')return;try{if('serviceWorker' in navigator&&navigator.serviceWorker.controller){const reg=await navigator.serviceWorker.ready;await reg.showNotification(title,{body,icon:'./icons/icon-192.png',tag:'shiftmemories-'+title,renotify:true});return}}catch(e){console.warn(e)}try{new Notification(title,{body,icon:'./icons/icon-192.png'})}catch(e){console.warn('Notification indisponible',e)}}
function checkReminders(){if(!state.settings.notify||!('Notification' in window)||Notification.permission!=='granted')return;const now=new Date();const cacheKey='shiftmemories:web:reminded:v1';let sent={};try{sent=JSON.parse(localStorage.getItem(cacheKey)||'{}')}catch(e){}let changed=false;for(const s of state.shifts){if(status(s)==='done')continue;for(const type of ['start','end']){if(type==='start'&&status(s)==='active')continue;const d=shiftDateTime(s,type);if(!d)continue;const mins=type==='start'?Number(state.settings.remindStart):Number(state.settings.remindEnd);const when=d.getTime()-mins*60000;const key=s.id+':'+type+':'+d.toISOString()+':'+mins;const diff=now.getTime()-when;if(diff>=0&&diff<=60000&&!sent[key]){displayNotification(type==='start'?'Votre garde commence bientôt':'Votre garde se termine bientôt',`${s.establishment||'Service'} · ${type==='start'?s.plannedStart:s.plannedEnd}`);sent[key]=now.toISOString();changed=true}}}if(changed){const recent=Object.fromEntries(Object.entries(sent).filter(([k,v])=>Date.now()-Date.parse(v)<40*86400000));try{localStorage.setItem(cacheKey,JSON.stringify(recent))}catch(e){}}}
function previousNext(month,offset){const [y,m]=month.split('-').map(Number);const date=new Date(y,m-1+offset,1);return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`}
function loadScript(src){return new Promise((resolve,reject)=>{const existing=document.querySelector(`script[data-src="${src}"]`);if(existing){if(existing.dataset.loaded)resolve();else existing.addEventListener('load',resolve,{once:true});return}const script=document.createElement('script');script.src=src;script.dataset.src=src;script.onload=()=>{script.dataset.loaded='1';resolve()};script.onerror=()=>reject(Error('Impossible de télécharger la bibliothèque nécessaire. Vérifiez la connexion Internet.'));document.head.appendChild(script)})}
function progress(message){const el=document.getElementById('import-progress');if(el)el.innerHTML=message?`<div class="processing"><span class="tiny-spinner"></span>${esc(message)}</div>`:''}
async function getWorker(){await loadScript('https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js');if(!window.Tesseract)throw Error('Moteur de reconnaissance non chargé.');return await Tesseract.createWorker('eng',1,{logger:log=>{if(log.status==='recognizing text')progress(`Reconnaissance du document : ${Math.round((log.progress||0)*100)} %`)}})}
async function imageOCR(file){progress('Chargement de la reconnaissance optique...');const worker=await getWorker();try{const result=await worker.recognize(file);return result.data.text||''}finally{await worker.terminate()}}
async function pdfText(file){progress('Lecture du PDF...');const version='3.11.174';await loadScript(`https://cdn.jsdelivr.net/npm/pdfjs-dist@${version}/build/pdf.min.js`);if(!window.pdfjsLib)throw Error('Lecteur PDF non chargé.');pdfjsLib.GlobalWorkerOptions.workerSrc=`https://cdn.jsdelivr.net/npm/pdfjs-dist@${version}/build/pdf.worker.min.js`;const data=new Uint8Array(await file.arrayBuffer());const doc=await pdfjsLib.getDocument({data}).promise;let result=[];const count=Math.min(doc.numPages,10);let worker=null;try{for(let p=1;p<=count;p++){progress(`Analyse du PDF : page ${p}/${count}...`);const page=await doc.getPage(p);const items=(await page.getTextContent()).items;const groups=new Map();for(const item of items){const y=Math.round(item.transform?.[5]/4)*4;const arr=groups.get(y)||[];arr.push({x:item.transform?.[4]||0,t:item.str});groups.set(y,arr)}const lines=[...groups.entries()].sort((a,b)=>b[0]-a[0]).map(([,xs])=>xs.sort((a,b)=>a.x-b.x).map(v=>v.t).join(' ').trim()).filter(Boolean);if(lines.join(' ').trim().length>12){result.push(lines.join('\n'));continue}if(!worker)worker=await getWorker();progress(`PDF scanné : OCR page ${p}/${count}...`);const view=page.getViewport({scale:1.7});const canvas=document.createElement('canvas');canvas.width=view.width;canvas.height=view.height;await page.render({canvasContext:canvas.getContext('2d'),viewport:view}).promise;const r=await worker.recognize(canvas);result.push(r.data.text||'')}}finally{if(worker)await worker.terminate()}return result.join('\n')}
function dateFound(line,month){let matches;let date=null;let strip=line;const iso=/(\b\d{4})[-/.](\d{1,2})[-/.](\d{1,2})\b/;const full=/(\b\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})\b/;const short=/(\b\d{1,2})[\/.](\d{1,2})(?!\d)/;const dayOnly=/^\s*(?:(?:lun\w*|mar\w*|mer\w*|jeu\w*|ven\w*|sam\w*|dim\w*|mon\w*|tue\w*|wed\w*|thu\w*|fri\w*|sat\w*|sun\w*|montag|dienstag|mittwoch|donnerstag|freitag|samstag|sonntag)\s+)?(\d{1,2})\b[\s:|\-–]+/i;const fmt=(y,m,d)=>`${String(y).padStart(4,'0')}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;if(matches=line.match(iso)){date=fmt(+matches[1],+matches[2],+matches[3]);strip=line.replace(matches[0],' ')}else if(matches=line.match(full)){let y=Number(matches[3]);if(y<100)y+=2000;date=fmt(y,+matches[2],+matches[1]);strip=line.replace(matches[0],' ')}else if(matches=line.match(short)){date=fmt(+month.slice(0,4),+matches[2],+matches[1]);strip=line.replace(matches[0],' ')}else if(matches=line.match(dayOnly)){date=fmt(+month.slice(0,4),+month.slice(5),+matches[1]);strip=line.replace(matches[0],' ')}return {date:isValidDay(date||'')?date:null,strip}}
function timesFound(line){const tokens=[];const pattern=/(?:^|[^\d])((?:[01]?\d|2[0-3]))\s*([:hH.])\s*([0-5]?\d)?(?=$|[^\d])/g;for(const m of line.matchAll(pattern)){const hour=Number(m[1]),minute=m[3]?Number(m[3]):0;if(hour<=23&&minute<=59)tokens.push(`${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}`)}if(tokens.length<2){const simplified=line.match(/(?:^|\s)([01]?\d|2[0-3])\s*[-–—]\s*([01]?\d|2[0-3])(?=\s|$)/);if(simplified)return [simplified[1].padStart(2,'0')+':00',simplified[2].padStart(2,'0')+':00']}return tokens.slice(0,2)}
function parseScheduleText(text,month,place){const lines=text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const candidates=[];let skip=0;for(const line of lines){const {date,strip}=dateFound(line,month);const times=timesFound(strip);if(date&&times.length>=2){candidates.push({date,plannedStart:times[0],plannedEnd:times[1],establishment:place||'',source:line});}else if(line.length>5)skip++}return {candidates,skip}}
function reviewPreview(){const container=document.getElementById('import-preview');if(!container)return;if(!importCandidates.length){container.innerHTML='<div class="review-alert" style="margin-top:16px">Aucun horaire complet n’a été trouvé. Vérifiez que chaque ligne contient une date et deux heures (ex. 02/11/2026 07:00 - 14:00). Les codes comme M, A ou N doivent être remplacés par leurs horaires.</div>';return}container.innerHTML=`<div class="section-heading"><div><h2>Vérifier les journées reconnues</h2><p>${importCandidates.length} ligne(s) détectée(s) · modifiables avant l’import</p></div><button class="text-btn" data-action="add-import-row">${ico('plus')} Ajouter une ligne</button></div><div class="card" style="padding:15px"><div class="review-alert">${ico('info')} Vérifiez les dates, les horaires et les gardes de nuit avant d’enregistrer. La reconnaissance n’est pas garantie pour tous les formats de planning.</div><div style="overflow-x:auto"><table class="review-table"><thead><tr><th>Date</th><th>Début</th><th>Fin</th><th>Lieu</th><th></th></tr></thead><tbody>${importCandidates.map((c,i)=>`<tr><td><input type="date" data-import-index="${i}" data-import-field="date" value="${esc(c.date)}"></td><td><input type="time" data-import-index="${i}" data-import-field="plannedStart" value="${esc(c.plannedStart)}"></td><td><input type="time" data-import-index="${i}" data-import-field="plannedEnd" value="${esc(c.plannedEnd)}"></td><td><input type="text" data-import-index="${i}" data-import-field="establishment" value="${esc(c.establishment)}" placeholder="Lieu"></td><td><button class="icon-button" data-action="remove-import-row" data-index="${i}" aria-label="Supprimer la ligne">${ico('close')}</button></td></tr>`).join('')}</tbody></table></div><button class="btn btn-primary" data-action="confirm-import" style="margin-top:13px">${ico('check')} Importer ${importCandidates.length} journée(s)</button></div>`;hydrateIcons(container)}
async function handleImportFile(file){if(!file)return;const allowed=['application/pdf','image/jpeg','image/png','image/webp'];if(!allowed.includes(file.type)&&!file.name.toLowerCase().endsWith('.pdf')){toast('Format non pris en charge : PDF, JPG, PNG ou WEBP seulement.',true);return}if(file.size>25*1024*1024){toast('Fichier trop grand (25 Mo maximum).',true);return}try{const text=file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf')?await pdfText(file):await imageOCR(file);const textarea=document.getElementById('import-text');if(textarea)textarea.value=text;progress('');if(!text.trim()){toast('Aucun texte reconnu : saisissez ou corrigez vos horaires.',true);return}importFromTextarea();toast('Document lu. Vérifiez chaque horaire avant import.')}catch(err){progress('');toast(err.message||'Impossible de lire le fichier.',true)}}
function importFromTextarea(){const text=document.getElementById('import-text')?.value||'';const month=document.getElementById('import-month')?.value||localDay().slice(0,7);const place=document.getElementById('import-place')?.value||'';const parsed=parseScheduleText(text,month,place);importCandidates=parsed.candidates;reviewPreview();if(importCandidates.length)document.getElementById('import-preview')?.scrollIntoView({behavior:'smooth',block:'start'})}
function confirmImport(){const valid=importCandidates.filter(s=>isValidDay(s.date)&&s.plannedStart&&s.plannedEnd);if(!valid.length){toast('Aucune journée valide à importer.',true);return}let added=0,duplicates=0;for(const c of valid){if(state.shifts.some(s=>s.date===c.date&&s.plannedStart===c.plannedStart&&s.plannedEnd===c.plannedEnd&&s.establishment===c.establishment)){duplicates++;continue}state.shifts.push({id:uniqueId(),date:c.date,plannedStart:c.plannedStart,plannedEnd:c.plannedEnd,actualStart:'',actualEnd:'',breakMinutes:0,rate:Number(state.settings.defaultRate)||0,establishment:c.establishment||'',note:'',hasPhoto:false,updatedAt:new Date().toISOString()});added++}persist();selectedMonth=valid[0].date.slice(0,7);navigate('calendar');toast(`${added} service(s) importé(s).${duplicates?' '+duplicates+' doublon(s) ignoré(s).':''}`)}
function bindEvents(){document.addEventListener('click',async e=>{const btn=e.target.closest('[data-route],[data-action]');if(!btn)return;if(btn.dataset.route){navigate(btn.dataset.route);return}const action=btn.dataset.action;const id=btn.dataset.id;switch(action){case'new-shift':closeModal();openShiftModal(null,btn.dataset.date);break;case'edit-shift':closeModal();openShiftModal(id);break;case'delete-shift':await deleteShift(id);break;case'close-modal':closeModal();break;case'view-day':viewDay(btn.dataset.date);break;case'start-shift':markStart(id);break;case'end-shift':markEnd(id);break;case'prev-month':selectedMonth=previousNext(selectedMonth,-1);render();break;case'next-month':selectedMonth=previousNext(selectedMonth,1);render();break;case'today-month':selectedMonth=localDay().slice(0,7);render();break;case'remove-photo':photoPending=null;photoRemove=true;document.getElementById('photo-preview-container').innerHTML='';btn.hidden=true;break;case'choose-import':document.getElementById('import-file')?.click();break;case'parse-import':importFromTextarea();break;case'add-import-row':importCandidates.push({date:localDay(),plannedStart:'07:00',plannedEnd:'14:00',establishment:document.getElementById('import-place')?.value||''});reviewPreview();break;case'remove-import-row':importCandidates.splice(Number(btn.dataset.index),1);reviewPreview();break;case'confirm-import':confirmImport();break;case'export-csv':exportCsv();break;case'export-ics':exportICS();break;case'print-report':window.print();break;case'export-backup':await exportBackup();break;case'restore-backup':document.getElementById('backup-restore-input').click();break;case'permission':await permission();break;}});
 document.addEventListener('submit',e=>{if(e.target.id==='shift-form'){e.preventDefault();saveShift(e.target)}else if(e.target.id==='settings-form'){e.preventDefault();const d=new FormData(e.target);state.settings.name=String(d.get('name')||'').trim().slice(0,70);state.settings.defaultPlace=String(d.get('defaultPlace')||'').trim().slice(0,160);state.settings.defaultRate=Math.max(0,Number(d.get('defaultRate'))||0);persist();render();toast('Préférences enregistrées.')}else if(e.target.id==='reminders-form'){e.preventDefault();const d=new FormData(e.target);state.settings.notify=d.has('notify');state.settings.remindStart=Math.min(180,Math.max(0,Number(d.get('remindStart'))||0));state.settings.remindEnd=Math.min(180,Math.max(0,Number(d.get('remindEnd'))||0));persist();render();toast('Rappels enregistrés.');checkReminders()}});
 document.addEventListener('change',e=>{if(e.target.id==='shift-photo')onPhotoChange(e.target.files?.[0]);if(e.target.id==='import-file')handleImportFile(e.target.files?.[0]);if(e.target.id==='backup-restore-input'){restoreBackup(e.target.files?.[0]);e.target.value=''}if(e.target.matches('[data-import-index]')){const c=importCandidates[Number(e.target.dataset.importIndex)];if(c)c[e.target.dataset.importField]=e.target.value}});
 document.addEventListener('input',e=>{if(e.target.matches('[data-import-index]')){const c=importCandidates[Number(e.target.dataset.importIndex)];if(c)c[e.target.dataset.importField]=e.target.value}});
 document.getElementById('menu-toggle').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});document.getElementById('modal-root').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});document.addEventListener('dragover',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();e.target.closest('#drop-zone').classList.add('dragging')}});document.addEventListener('dragleave',e=>{if(e.target.closest('#drop-zone'))e.target.closest('#drop-zone').classList.remove('dragging')});document.addEventListener('drop',e=>{if(e.target.closest('#drop-zone')){e.preventDefault();e.target.closest('#drop-zone').classList.remove('dragging');handleImportFile(e.dataTransfer.files?.[0])}});}
function initialize(){hydrateIcons();bindEvents();render();if('serviceWorker' in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('Service worker indisponible',err))}checkReminders();notificationTimer=setInterval(checkReminders,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkReminders()})}
window.addEventListener('DOMContentLoaded',initialize);
